def ui_sentence(value: object) -> str:
    """Sentence-case display text while preserving market terminology."""
    text = str(value)
    if "_" in text and re.fullmatch(r"[A-ZÀ-Ỹ0-9_]+", text):
        return text
    letters = [char for char in text if char.isalpha()]
    if len(letters) < 2 or sum(char.isupper() for char in letters) / len(letters) < .82:
        return text
    protected: dict[str, str] = {}
    for index, term in enumerate(sorted(_PRESERVE_TERMS, key=len, reverse=True)):
        marker = f"§{index}§"
        if re.search(re.escape(term), text, flags=re.IGNORECASE):
            text = re.sub(re.escape(term), marker, text, flags=re.IGNORECASE)
            protected[marker] = term
    text = text.lower()
    for marker, term in protected.items():
        text = text.replace(marker, term)
    text = text.replace("VIỆT NAM", "Việt Nam").replace("WYCKOFF", "Wyckoff").replace("FIBONACCI", "Fibonacci")
    for index, char in enumerate(text):
        if char.isalpha():
            text = text[:index] + char.upper() + text[index + 1:]
            break
    return text


def tr(language: str, key: str, **values) -> str:
    text = T.get(language, T["vi"]).get(key, T["vi"].get(key, key))
    text = text.format(**values) if values else text
    return text if key in _CASE_EXEMPT_KEYS else ui_sentence(text)


